UPDATE dbo.sa05_user SET sa10_usertypeid=4 WHERE UserId=1;
DECLARE @Submission uniqueidentifier=NEWID(),@StageId int=(SELECT StageId FROM dbo.m_RSTStageMaster WHERE StageCode=N'BILL_GENERATED');
EXEC dbo.sp_BillingSave 'DIRECT-FULL',@Submission,N'{}',100,1000,0,0,0,0,1000,1;
DECLARE @BillId int=(SELECT BillId FROM dbo.t_BillingBill WHERE RSTNumber='DIRECT-FULL');
IF @BillId IS NULL THROW 51000,'Bill was not saved.',1;
IF NOT EXISTS(SELECT 1 FROM dbo.t_RSTMaster WHERE RSTNumber='DIRECT-FULL' AND CurrentStageId=@StageId) THROW 51000,'Current stage was not updated.',1;
IF NOT EXISTS(SELECT 1 FROM dbo.t_RSTProgressWork WHERE RSTNumber='DIRECT-FULL' AND StageId=@StageId AND IsActive=1 AND CompletedAt IS NOT NULL AND CreatedBy=1 AND Remarks=CONCAT(N'Bill RM-',@BillId)) THROW 51000,'Bill progress metadata missing.',1;
IF (SELECT COUNT(*) FROM dbo.t_RSTProgressWork WHERE RSTNumber='DIRECT-FULL' AND IsActive=1)<>1 THROW 51000,'Multiple active stages.',1;
DECLARE @ProgressCount int=(SELECT COUNT(*) FROM dbo.t_RSTProgressWork WHERE RSTNumber='DIRECT-FULL');
EXEC dbo.sp_BillingSave 'DIRECT-FULL',@Submission,N'{}',100,1000,0,0,0,0,1000,1;
IF (SELECT COUNT(*) FROM dbo.t_RSTProgressWork WHERE RSTNumber='DIRECT-FULL')<>@ProgressCount OR (SELECT COUNT(*) FROM dbo.t_BillingBill WHERE RSTNumber='DIRECT-FULL')<>1 THROW 51000,'Retry duplicated bill/progress.',1;
EXEC dbo.sp_MoveRSTProgress 'DIRECT-FULL',9,'Completed',1;
EXEC dbo.sp_BillingSave 'DIRECT-FULL',@Submission,N'{}',100,1000,0,0,0,0,1000,1;
IF NOT EXISTS(SELECT 1 FROM dbo.t_RSTMaster WHERE RSTNumber='DIRECT-FULL' AND CurrentStageId=9) THROW 51000,'Retry reset a later stage.',1;
EXEC(N'CREATE TRIGGER dbo.BillingProgressFailure ON dbo.t_RSTProgressWork AFTER INSERT AS BEGIN THROW 51001,''Simulated progress failure'',1; END;');
DECLARE @Blocked bit=0;
SET @Submission=NEWID();
BEGIN TRY EXEC dbo.sp_BillingSave 'DIRECT-STAGE-9',@Submission,N'{}',100,1000,0,0,0,0,1000,1;
END TRY BEGIN CATCH IF ERROR_NUMBER()=51001 SET @Blocked=1; ELSE THROW; END CATCH;
IF @Blocked=0 OR EXISTS(SELECT 1 FROM dbo.t_BillingBill WHERE RSTNumber='DIRECT-STAGE-9') THROW 51000,'Failed progress left a saved bill.',1;
IF EXISTS(SELECT 1 FROM dbo.t_RSTMaster WHERE RSTNumber='DIRECT-STAGE-9' AND CurrentStageId=@StageId) THROW 51000,'Failed progress changed current stage.',1;
DROP TRIGGER dbo.BillingProgressFailure;
IF @@TRANCOUNT<>0 THROW 51000,'Billing transaction leaked.',1;
PRINT 'PASS: bill and progress atomic save, metadata, current stage, retry and failure rollback.';
